#!/usr/bin/env bash
# Rebuilds the WenKai subset used for brand and album display headings on the
# site (assets/fonts/wenkai.woff2 + wenkai.css).
#
# The site ships no build step otherwise: run this only when Chinese copy that
# renders in --display-zh changes, then commit the regenerated files.
#
# Requires the local toolchain (gitignored):
#   tools/fonts/LXGWWenKai-Regular.ttf
#   tools/venvs/fonts/{bin/python,bin/pyftsubset}   (fonttools + brotli)
set -euo pipefail

repo="$(cd "$(dirname "$0")/.." && pwd)"
site="$repo"
font="$repo/tools/fonts/LXGWWenKai-Regular.ttf"
py="$repo/tools/venvs/fonts/bin/python"
pyftsubset="$repo/tools/venvs/fonts/bin/pyftsubset"

[ -f "$font" ] || { echo "missing font: $font" >&2; exit 1; }
[ -x "$py" ] || { echo "missing venv: $repo/tools/venvs/fonts" >&2; exit 1; }

chars="$(mktemp)"
trap 'rm -f "$chars"' EXIT

"$py" - "$site" "$chars" <<'PYEOF'
import sys
from pathlib import Path

site, out = Path(sys.argv[1]), Path(sys.argv[2])
sources = [site / 'index.html', site / 'src' / 'zh-CN.mjs']
chars = set()
for path in sources:
    for char in path.read_text(encoding='utf-8'):
        code = ord(char)
        if 0x3000 <= code <= 0x303F or 0x4E00 <= code <= 0x9FFF or 0xFF00 <= code <= 0xFFEF:
            chars.add(char)
out.write_text(''.join(sorted(chars)), encoding='utf-8')
print(f'{len(chars)} characters', file=sys.stderr)
PYEOF

"$pyftsubset" "$font" --text-file="$chars" --flavor=woff2 \
  --output-file="$site/assets/fonts/wenkai.woff2" \
  --layout-features='*' --drop-tables+=DSIG --name-IDs='*'

cat > "$site/assets/fonts/wenkai.css" <<'CSSEOF'
/* LXGW WenKai 1.522, OFL-1.1. Original notice: OFL.txt.
   Subset for brand and album display headings only, generated by
   tools/build-brand-kai-font.sh from the current Chinese copy. */
@font-face{font-family:"LXGW WenKai";src:url("./wenkai.woff2")format("woff2");font-style:normal;font-display:swap;font-weight:400;unicode-range:U+3000-303F,U+4E00-9FFF,U+FF00-FFEF}
CSSEOF

ls -l "$site/assets/fonts/wenkai.woff2"
